<?php
namespace App\Services; use App\Core\Database;use App\Core\Auth;
final class ExceptionService{public function create(array $d):int{$s=Database::pdo()->prepare('INSERT INTO exception_records(tenant_id,client_id,service_id,project_id,workflow_instance_id,type,severity,message,status,ai_confidence,assigned_user_id,created_at) VALUES(1,?,?,?,?,?,?,?,?,?,?,NOW())');$s->execute([$d['client_id']??null,$d['service_id']??null,$d['project_id']??null,$d['workflow_instance_id']??null,$d['type'],$d['severity']??'medium',$d['message'],$d['status']??'open',$d['ai_confidence']??null,$d['assigned_user_id']??Auth::id()]);return (int)Database::pdo()->lastInsertId();}public function resolve(int $id):void{Database::pdo()->prepare('UPDATE exception_records SET status="resolved",resolved_at=NOW() WHERE id=?')->execute([$id]);}}
